/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
src = Path('/home/user/Desktop/doc_proc')
out = Path('/tmp/concat_source.rtf')
files = sorted([p for p in src.glob('*.txt')], key=lambda p: int(p.stem) if p.stem.isdigit() else p.name)
def rtf_escape(s):
    out = []
    for ch in s:
        code = ord(ch)
        if ch == '\\\\':
            out.append('\\\\\\\\')
        elif ch == '{':
            out.append('\\\\{')
        elif ch == '}':
            out.append('\\\\}')
        elif ch == '\\n':
            out.append('\\\\line\\n')
        elif ch == '\\r':
            pass
        elif code > 127:
            if code > 32767:
                code -= 65536
            out.append(f'\\\\u{code}?')
        else:
            out.append(ch)
    return ''.join(out)
body = '\\\\par\\n'.join(rtf_escape(p.read_text(encoding='utf-8')) for p in files)
rtf = '{\\\\rtf1\\\\ansi\\\\deff0{\\\\fonttbl{\\\\f0 Liberation Serif;}}\\\\fs20\\n' + body + '\\n}'
out.write_text(rtf, encoding='utf-8')
print(out)
PY
rm -f /home/user/Desktop/concat.docx /home/user/Desktop/concat_source.docx
